:root {
  --color-bg: #f0ebe1;
  --color-border: #b8a98a;
  --color-header-bg: #4a6741;
  --color-header-text: #f0ebe1;
  --color-title: #2e3d2c;
  --color-herb-name: #3a5436;
  --color-latin: #7a6f5c;
  --color-label: #7a6f5c;
  --color-value: #2e3d2c;
  --color-badge-bg: #d4c9a8;
  --color-badge-text: #4a6741;
  --color-divider: #c9bda0;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
}

.herb-tag {
  background-color: var(--color-bg);
  border: 2px solid var(--color-border);
  border-radius: 12px;
  width: 300px;
  overflow: hidden;
}

.tag-header {
  background-color: var(--color-header-bg);
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px 16px;
}

.tag-icon {
  font-size: 20px;
  line-height: 1;
}

.tag-title {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--color-header-text);
  margin: 0;
}

.tag-body {
  padding: 16px 16px 12px;
}

.herb-name {
  font-size: 22px;
  font-weight: 800;
  color: var(--color-herb-name);
  margin: 0 0 2px;
  line-height: 1.1;
}

.herb-latin {
  font-size: 12px;
  font-style: italic;
  color: var(--color-latin);
  margin: 0 0 14px;
}

.herb-details {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.herb-details li {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-bottom: 6px;
  border-bottom: 1px solid var(--color-divider);
}

.herb-details li:last-child {
  border-bottom: none;
  padding-bottom: 0;
}

.detail-label {
  font-size: 12px;
  font-weight: 600;
  color: var(--color-label);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.detail-value {
  font-size: 13px;
  font-weight: 700;
  color: var(--color-value);
}

.tag-footer {
  padding: 10px 16px;
  border-top: 2px dashed var(--color-border);
  display: flex;
  justify-content: center;
}

.tag-badge {
  background-color: var(--color-badge-bg);
  color: var(--color-badge-text);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 4px 12px;
  border-radius: 20px;
}
